import sys, os, io
import math
from collections import defaultdict, deque

def ii():
	return int(input())

def li():
	return list(map(int, input().split()))
if os.path.exists('input.txt'):
	sys.stdin = open('input.txt', 'r')
	sys.stdout = open('output.txt', 'w')
(n, m) = li()
a = li()
g = [[] for i in range(n)]
s = sum(a)
for i in range(m):
	(a, b) = li()
	a -= 1
	b -= 1
	g[a].append(b)
	g[b].append(a)
q = ii()
c = m
for i in range(q):
	l = [x for x in input().split()]
	if l[0] == '?':
		print(s - n * (n - 1) // 2 + 2 * c)
	elif l[0] == '+':
		c += 1
	else:
		c -= 1
